void mainImage( out vec4 O, vec2 u )
{
    vec2  U = sin(1.571*u);  U /= fwidth(U);                    // strips
    float v = textureLod(iChannel0, u/iResolution.xy,2.).r;     // source video
    O = vec4( v > .6 ? max(U.x,U.y) : v <.33 ? U.x : U.y )/10.; // quantization selects strip direction
}
